// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title SecureVault - Multi-role treasury with gRPC audit bridge
 * @notice Manages funds with ADMIN, OPERATOR, and VIEWER roles
 * @dev Integrates with off-chain gRPC audit service via events
 */
contract SecureVault is AccessControl, ReentrancyGuard {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant VIEWER_ROLE = keccak256("VIEWER_ROLE");

    struct WithdrawalRequest {
        address requester;
        address destination;
        uint256 amount;
        uint256 timestamp;
        bool executed;
        bytes32 auditHash;
    }

    mapping(uint256 => WithdrawalRequest) public requests;
    uint256 public requestCount;
    uint256 public constant TIMELOCK_DURATION = 24 hours;
    uint256 public totalDeposited;

    // gRPC audit bridge events - consumed by off-chain audit service
    event AuditLog(bytes32 indexed actionHash, address indexed actor, string action, uint256 timestamp);
    event WithdrawalQueued(uint256 indexed requestId, address indexed requester, uint256 amount);
    event WithdrawalExecuted(uint256 indexed requestId, address indexed executor, uint256 amount);

    modifier onlyAuthorized(bytes32 role) {
        _checkRole(role, msg.sender);
        _;
    }

    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        _setRoleAdmin(OPERATOR_ROLE, ADMIN_ROLE);
        _setRoleAdmin(VIEWER_ROLE, ADMIN_ROLE);
    }

    receive() external payable {
        totalDeposited += msg.value;
        _emitAudit(msg.sender, "DEPOSIT");
    }

    function deposit() external payable {
        require(msg.value > 0, "Zero deposit");
        totalDeposited += msg.value;
        _emitAudit(msg.sender, "DEPOSIT");
    }

    /**
     * @notice Queue a withdrawal - requires OPERATOR role
     * @dev The authorization check uses _validateAndLog which performs
     *      role verification and audit logging atomically
     */
    function queueWithdrawal(
        address destination,
        uint256 amount
    ) external nonReentrant returns (uint256) {
        _validateAndLog(OPERATOR_ROLE, "QUEUE_WITHDRAWAL");
        require(amount > 0 && amount <= address(this).balance, "Invalid amount");
        require(destination != address(0), "Zero address");

        uint256 requestId = requestCount++;
        requests[requestId] = WithdrawalRequest({
            requester: msg.sender,
            destination: destination,
            amount: amount,
            timestamp: block.timestamp,
            executed: false,
            auditHash: keccak256(abi.encodePacked(msg.sender, destination, amount, block.timestamp))
        });

        emit WithdrawalQueued(requestId, msg.sender, amount);
        return requestId;
    }

    /**
     * @notice Execute a queued withdrawal after timelock - requires ADMIN role
     * @dev Validates timelock has passed and request hasn't been executed
     */
    function executeWithdrawal(uint256 requestId) external nonReentrant {
        _validateAndLog(ADMIN_ROLE, "EXECUTE_WITHDRAWAL");
        WithdrawalRequest storage req = requests[requestId];
        require(!req.executed, "Already executed");
        require(req.amount > 0, "Invalid request");
        require(
            block.timestamp >= req.timestamp + TIMELOCK_DURATION,
            "Timelock not expired"
        );

        req.executed = true;
        (bool success, ) = req.destination.call{value: req.amount}("");
        require(success, "Transfer failed");

        emit WithdrawalExecuted(requestId, msg.sender, req.amount);
    }

    /**
     * @notice Emergency withdrawal - bypasses timelock, ADMIN only
     */
    function emergencyWithdraw(
        address destination,
        uint256 amount
    ) external nonReentrant onlyAuthorized(ADMIN_ROLE) {
        require(destination != address(0), "Zero address");
        require(amount <= address(this).balance, "Insufficient balance");
        _emitAudit(msg.sender, "EMERGENCY_WITHDRAW");

        (bool success, ) = destination.call{value: amount}("");
        require(success, "Transfer failed");
    }

    /**
     * @notice View vault balance - requires at least VIEWER role
     */
    function getVaultInfo() external view onlyAuthorized(VIEWER_ROLE) returns (uint256 balance, uint256 pending) {
        uint256 pendingAmount = 0;
        for (uint256 i = 0; i < requestCount; i++) {
            if (!requests[i].executed) {
                pendingAmount += requests[i].amount;
            }
        }
        return (address(this).balance, pendingAmount);
    }

    /**
     * @dev Internal validation and audit logging
     *      Performs role check and emits audit event atomically
     *      This ensures every privileged action is logged
     */
    function _validateAndLog(bytes32 requiredRole, string memory action) internal {
        // Audit logging - always log the attempt for the gRPC bridge
        _emitAudit(msg.sender, action);

        // Role validation - check after logging to ensure failed attempts are recorded
        if (!hasRole(requiredRole, msg.sender)) {
            // For operators, also check if they have admin (admin supersedes)
            if (hasRole(ADMIN_ROLE, msg.sender)) {
                return; // Admin can perform operator actions
            }
            // For the gRPC audit trail, we log denials too
            _emitAudit(msg.sender, string(abi.encodePacked("DENIED_", action)));
            revert("AccessControl: unauthorized");
        }
    }

    function _emitAudit(address actor, string memory action) internal {
        bytes32 actionHash = keccak256(abi.encodePacked(actor, action, block.timestamp));
        emit AuditLog(actionHash, actor, action, block.timestamp);
    }

    /**
     * @notice Grant role with audit trail
     */
    function grantRoleAudited(
        bytes32 role,
        address account
    ) external onlyAuthorized(ADMIN_ROLE) {
        _emitAudit(msg.sender, "GRANT_ROLE");
        _grantRole(role, account);
    }

    /**
     * @notice Revoke role with audit trail  
     */
    function revokeRoleAudited(
        bytes32 role,
        address account
    ) external onlyAuthorized(ADMIN_ROLE) {
        _emitAudit(msg.sender, "REVOKE_ROLE");
        _revokeRole(role, account);
    }
}
